export function buildStatementArbitration3to8PdfDoc(form = {}) {
  const claimant = form.claimant || {};
  const bank = form.bankDetails || {};
  const debtors = resolveDebtors(form);
  const debtor = debtors[0] || {};
  const signerFio = form.signer && form.signer.fio;
  const housingPenalty = (form.skanReport && form.skanReport.housingPenalty) || {};
  const claimantName = String(claimant.name || bank.recipientName || '').trim();
  const claimantInn = String(claimant.inn || bank.inn || '').trim();
  const requirements = String(form.requirements || '');
  const contract = contractNoDateParts(form);

  const debtorNames = joinDebtorNames(debtors);
  const ownerName = debtorDisplayName(debtor);
  const penaltyRange = penaltyPeriodRange(housingPenalty);

  const debtorBlocks = debtors.flatMap((d, index) => {
    const lines = debtorHeaderLines(d);
    return index < debtors.length - 1 ? [...lines, headerLine([plain(' ')])] : lines;
  });

  const bankAccount = String(bank.account || '').trim();
  const bankName = String(bank.bankName || '').trim();
  const bankBik = String(bank.bik || '').trim();
  const bankCorr = String(bank.corrAccount || '').trim();
  const hasBank = bankAccount || bankName || bankBik || bankCorr;
  const claimantAddress = String(claimant.address || '').trim();

  const content = [
    headerLine([label('Арбитражный суд')]),
    headerLine([plain(' ')]),
    headerLine([label('Взыскатель:')]),
    ...optionalHeaderLine(claimantName),
    ...(claimantInn ? [headerLine([plain(`ИНН ${claimantInn}`)])] : []),
    ...optionalHeaderLine(claimantAddress),
    ...(hasBank
      ? [
          headerLine([plain(' ')]),
          headerLine([label('реквизиты счета:')]),
          ...(bankAccount ? [headerLine([plain(`р/с ${bankAccount}`)])] : []),
          ...optionalHeaderLine(bankName),
          ...(bankBik ? [headerLine([plain(`БИК ${bankBik}`)])] : []),
          ...(bankCorr ? [headerLine([plain(`кор/с ${bankCorr}`)])] : []),
        ]
      : []),
    headerLine([plain(' ')]),
    headerLine([label('Должник:')]),
    ...debtorBlocks,

    {
      text: 'Заявление о вынесении судебного приказа',
      alignment: 'center',
      bold: true,
      margin: [0, 24, 0, 24],
    },

    ...buildIntroParagraphs(requirements, claimantName, contract),

    bodyParagraph([
      plain('Как следует из акта сверки взаимных расчетов, по договору № '),
      field(contract.number, '___'),
      plain(' от '),
      field(contract.date, '___'),
      plain(' числится задолженность в размере '),
      moneyField(housingPenalty.principalTotal, 'сумма'),
      plain(' руб.'),
    ]),
    bodyParagraph([
      plain(
        'В соответствии со ст. 309 ГК РФ своевременная оплата такой задолженности является обязанностью потребителя.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Поскольку данная задолженность им просрочена, для потребителя, несвоевременно и (или) не полностью внесшего плату,'
      ),
    ]),
    ...buildPenaltyLawParagraph(requirements),
    bodyParagraph([
      plain('По расчету взыскателя (прилагается) сумма такой пени составляет '),
      moneyField(housingPenalty.penaltyTotal, 'размер'),
      plain(' руб.'),
    ]),
    bodyParagraph([plain('На основании изложенного, а также ст. 229.2, 229.3 АПК РФ,')]),

    { text: 'ПРОШУ:', alignment: 'center', bold: true, margin: [0, 12, 0, 12] },

    bodyParagraph([
      plain('- вынести судебный приказ о взыскании с '),
      field(debtorNames || ownerName, 'такого-то'),
      plain(' задолженности в размере '),
      moneyField(housingPenalty.principalTotal, 'сумма'),
      plain(' руб., пени за период с '),
      field(penaltyRange.from, 'дата'),
      plain(' по '),
      field(penaltyRange.to, 'дата'),
      plain(' в размере '),
      moneyField(housingPenalty.penaltyTotal, 'сумма'),
      plain(' руб., расходов по уплате госпошлины в размере '),
      label(ARBITRATION_ORDER_DUTY),
      plain(' руб.'),
    ]),

    { text: 'Приложения:', margin: [24, 12, 0, 4] },
    { text: '1) почтовая квитанция о направлении заявления в адрес должника,', margin: [24, 0, 0, 0] },
    {
      text: [
        plain('2) доказательства уплаты госпошлины в размере '),
        label(ARBITRATION_ORDER_DUTY),
        plain(' руб.,'),
      ],
      margin: [24, 0, 0, 0],
    },
    {
      text: [
        plain('3) договор № '),
        field(contract.number, '___'),
        plain(' от '),
        field(contract.date, '___'),
      ],
      margin: [24, 0, 0, 0],
    },
    { text: '4) УПД за спорные периоды,', margin: [24, 0, 0, 0] },
    { text: '5) акт сверки взаимных расчетов,', margin: [24, 0, 0, 0] },
    { text: '6) расчет пени,', margin: [24, 0, 0, 0] },
    { text: '7) копия доверенности представителя.', margin: [24, 0, 0, 0] },

    { text: [field(signerFio, 'ФИО подписанта')], margin: [24, 24, 0, 0] },
  ];

  return {
    content,
    defaultStyle: { fontSize: 11 },
    pageMargins: [56, 56, 56, 56],
  };
}
