import JSZip from 'jszip';

export function emptyBankDetails() {
  return {
    recipientName: '',
    inn: '',
    kpp: '',
    ogrn: '',
    account: '',
    bankName: '',
    bik: '',
    corrAccount: '',
    bankInn: '',
    bankKpp: '',
  };
}

function cleanSpaces(value) {
  return String(value || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function digitsOnly(value) {
  return String(value || '').replace(/\D/g, '');
}

function pick(block, re) {
  const match = String(block || '').match(re);
  return match ? cleanSpaces(match[1]) : '';
}

function firstPick(block, patterns) {
  for (let i = 0; i < patterns.length; i += 1) {
    const value = pick(block, patterns[i]);
    if (value) return value;
  }
  return '';
}

function decodeXmlEntities(text) {
  return String(text || '')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, n) => String.fromCharCode(parseInt(n, 16)));
}

/** Текст из docx (word/document.xml). */
export async function extractDocxText(file) {
  const buffer = await file.arrayBuffer();
  const zip = await JSZip.loadAsync(buffer);
  const entry = zip.file('word/document.xml');
  if (!entry) return '';

  const xml = await entry.async('string');
  return decodeXmlEntities(
    xml
      .replace(/<w:tab[^/]*\/>/g, '\t')
      .replace(/<\/w:p>/g, '\n')
      .replace(/<[^>]+>/g, '')
  )
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/** СберБизнес: блоки «Получатель» / «Банк получателя» с метками «Наименование:». */
function parseSberBusinessLayout(text) {
  const parts = text.split(/Банк\s+получателя/i);
  const recipientBlock = parts[0] || text;
  const bankBlock = parts[1] || '';

  const details = emptyBankDetails();
  details.recipientName = pick(
    recipientBlock,
    /Наименование\s*:\s*(.+?)(?=\s*(?:ИНН|КПП|ОГРН|Расч|$))/i
  );
  details.inn = digitsOnly(pick(recipientBlock, /ИНН\s*:\s*([0-9\s]+)/i)).slice(0, 12);
  details.kpp = digitsOnly(pick(recipientBlock, /КПП\s*:\s*([0-9\s]+)/i)).slice(0, 9);
  details.ogrn = digitsOnly(pick(recipientBlock, /ОГРН\s*:\s*([0-9\s]+)/i)).slice(0, 15);
  details.account = digitsOnly(
    pick(recipientBlock, /Расч[её]тный\s*сч[её]т\s*:\s*([0-9\s]+)/i)
  ).slice(0, 20);

  details.bankName = pick(bankBlock, /Наименование\s*:\s*(.+?)(?=\s*(?:БИК|Корсч|ИНН|КПП|$))/i);
  details.bik = digitsOnly(pick(bankBlock, /БИК\s*:\s*([0-9\s]+)/i)).slice(0, 9);
  details.corrAccount = digitsOnly(pick(bankBlock, /Корсч[её]т\s*:\s*([0-9\s]+)/i)).slice(0, 20);
  details.bankInn = digitsOnly(pick(bankBlock, /ИНН\s*:\s*([0-9\s]+)/i)).slice(0, 12);
  details.bankKpp = digitsOnly(pick(bankBlock, /КПП\s*:\s*([0-9\s]+)/i)).slice(0, 9);

  return details;
}

/**
 * Т-Банк и похожие справки:
 * «Банк-получатель: … К/с №: … БИК: … ИНН/КПП: … Счет получателя: … Получатель: …»
 */
function parseLetterLayout(text) {
  const details = emptyBankDetails();

  // Не путать с «Банк-получатель: …» (без lookbehind — webpack 4 / старые браузеры)
  details.recipientName = firstPick(text, [
    /(?:^|[^А-Яа-яA-Za-zЁё-])Получатель\s*:\s*(.+?)(?=\s*(?:Назначение\s*платежа|С\s+уважением|$))/i,
  ]);

  details.account = digitsOnly(
    firstPick(text, [
      /Сч[её]т\s+получателя\s*:\s*([0-9\s]+)/i,
      /открыт\s+сч[её]т\s*№?\s*([0-9\s]{16,})/i,
      /Расч[её]тный\s*сч[её]т\s*:\s*([0-9\s]+)/i,
    ])
  ).slice(0, 20);

  details.bankName = firstPick(text, [
    /Банк[-–—\s]*получател[ья]\s*:\s*(.+?)(?=\s*(?:К\s*\/\s*с|Корсч|БИК|ИНН|$))/i,
  ]);

  details.bik = digitsOnly(pick(text, /БИК\s*:\s*([0-9\s]+)/i)).slice(0, 9);

  details.corrAccount = digitsOnly(
    firstPick(text, [
      /К\s*\/\s*с\s*№?\s*:\s*([0-9\s]+)/i,
      /Корсч[её]т\s*:\s*([0-9\s]+)/i,
      /к\s*\/\s*с\s+([0-9]{20})/i,
    ])
  ).slice(0, 20);

  const innKpp = text.match(/ИНН\s*\/\s*КПП\s*:\s*([0-9]+)\s*\/\s*([0-9]+)/i);
  if (innKpp) {
    details.bankInn = innKpp[1].slice(0, 12);
    details.bankKpp = innKpp[2].slice(0, 9);
  } else {
    details.bankInn = digitsOnly(pick(text, /БИК[\s\S]{0,80}?ИНН\s*:\s*([0-9\s]+)/i)).slice(0, 12);
    details.bankKpp = digitsOnly(pick(text, /БИК[\s\S]{0,120}?КПП\s*:\s*([0-9\s]+)/i)).slice(0, 9);
  }

  // У физлица в справке ИНН получателя часто нет — не путаем с ИНН банка.
  details.inn = '';
  details.kpp = '';
  details.ogrn = '';

  return details;
}

/**
 * Разбор текста реквизитов (СберБизнес docx, Т-Банк и похожие выгрузки).
 */
export function parseBankDetailsFromText(rawText) {
  const text = cleanSpaces(rawText);
  if (!text) return emptyBankDetails();

  const isSberBusiness =
    /Банк\s+получателя/i.test(text) &&
    /Наименование\s*:/i.test(text) &&
    /Расч[её]тный\s*сч[её]т\s*:/i.test(text);

  if (isSberBusiness) {
    return parseSberBusinessLayout(text);
  }

  return parseLetterLayout(text);
}

/**
 * @param {File|Blob} file
 * @returns {Promise<ReturnType<typeof emptyBankDetails>>}
 */
export async function parseBankDetailsFile(file) {
  if (!file) return emptyBankDetails();

  const name = String(file.name || '').toLowerCase();
  const type = String(file.type || '').toLowerCase();
  const isDocx =
    name.endsWith('.docx') ||
    type.includes('wordprocessingml') ||
    type.includes('officedocument.wordprocessingml');

  if (!isDocx) {
    console.warn('parseBankDetailsFile: поддерживается только .docx', name || type);
    return emptyBankDetails();
  }

  try {
    const text = await extractDocxText(file);
    return parseBankDetailsFromText(text);
  } catch (error) {
    console.error('Не удалось разобрать docx реквизитов', error);
    return emptyBankDetails();
  }
}
