/**
 * Неустойка по кредиту (опция 9).
 * - график[i] ↔ блок выписки[i] (колонки заказчика);
 * - списание: просроч.% → просроч.ОД → тек.% → тек.ОД;
 * - старт пени = день после даты платежа из графика;
 * - база = просроченный ОД + просроченные %;
 * - ставка п.5.1: доля ключевой «сегодня» ИЛИ % в день.
 */

import { getKeyRateAt } from './cbrKeyRates';
import { addDays, formatRuDate, parseRuDate, todayRuDate } from './calculateHousingPenalty';
import { applyLegalAllocation, emptyLoanAllocationState } from './calculateLoanDebt';

function toAmount(value) {
  if (value == null || value === '' || value === '-' || value === '---') return 0;
  if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
  let s = String(value).replace(/\u00a0/g, '').replace(/\s/g, '').trim();
  if (!s || s === '-' || s === '---') return 0;
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) s = s.replace(/,/g, '');
  else if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',') && s.includes('.')) {
    s =
      s.lastIndexOf(',') > s.lastIndexOf('.')
        ? s.replace(/\./g, '').replace(',', '.')
        : s.replace(/,/g, '');
  } else if (s.includes(',')) s = s.replace(',', '.');
  const num = Number(s);
  return Number.isFinite(num) ? num : 0;
}

function roundMoney(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function daysBetween(from, to) {
  return Math.round((to.getTime() - from.getTime()) / 86400000);
}

export function parseBankRateFraction(raw) {
  const m = String(raw || '')
    .trim()
    .match(/(\d+)\s*\/\s*(\d+)/);
  if (!m) return null;
  const den = Number(m[2]);
  if (!den) return null;
  return Number(m[1]) / den;
}

export function parseDebtDailyRate(raw) {
  const s = String(raw || '').trim();
  if (!s) return null;
  const m = s.match(/(\d+[.,]?\d*)/);
  if (!m) return null;
  let n = Number(m[1].replace(',', '.'));
  if (!Number.isFinite(n) || n < 0) return null;
  if (/^\d+$/.test(m[1])) n /= 100;
  return n / 100;
}

export function resolveLoanPenaltyRate(penaltyDetails = {}) {
  const debtRaw = String(penaltyDetails.debtRate || '').trim();
  const bankRaw = String(penaltyDetails.bankRate || '').trim();

  const dailyFromDebt = parseDebtDailyRate(debtRaw);
  if (debtRaw && dailyFromDebt != null && dailyFromDebt > 0) {
    return {
      mode: 'fixed',
      dailyFactor: dailyFromDebt,
      keyRateToday: null,
      fraction: null,
      label: debtRaw,
    };
  }

  const fraction = parseBankRateFraction(bankRaw);
  if (bankRaw && fraction != null && fraction > 0) {
    const keyRateToday = getKeyRateAt(parseRuDate(todayRuDate()));
    return {
      mode: 'keyRate',
      dailyFactor: fraction * keyRateToday,
      keyRateToday,
      fraction,
      label: bankRaw,
    };
  }

  return null;
}

function overdueBase(state) {
  return roundMoney(state.overdueInterest + state.overduePrincipal);
}

function pushSegment(segments, { debt, from, to, dailyFactor, rateLabel, closedByPayment }) {
  if (!(debt > 0) || to.getTime() <= from.getTime()) return;
  const days = daysBetween(from, to);
  if (days <= 0) return;
  segments.push({
    debt: roundMoney(debt),
    from: formatRuDate(from),
    to: formatRuDate(to),
    days,
    rate: dailyFactor,
    rateLabel,
    penalty: roundMoney(debt * dailyFactor * days),
    closedByPayment: Boolean(closedByPayment),
  });
}

export function calculateLoanPenalty(paymentSchedule, legalAccountRows, options = {}) {
  const schedulePayments = paymentSchedule?.payments || [];
  const ledgerPeriods = legalAccountRows?.periods || [];
  const rate = resolveLoanPenaltyRate(options.penaltyDetails || {});
  if (!schedulePayments.length || !ledgerPeriods.length || !rate) return null;

  const asOfDate = parseRuDate(options.asOfDate) || parseRuDate(todayRuDate());
  const count = Math.min(schedulePayments.length, ledgerPeriods.length);
  const state = emptyLoanAllocationState();
  const periodResults = [];
  let penaltyFrom = '';
  let penaltyCursor = null;

  for (let i = 0; i < count; i += 1) {
    const install = schedulePayments[i];
    const dueDate = parseRuDate(install.date);
    const interest = toAmount(install.interest);
    const principal = toAmount(install.principal);
    const total = toAmount(install.total) || roundMoney(interest + principal);
    if (!dueDate || !(total > 0)) continue;

    const segments = [];
    const paymentRows = [];
    const dayAfter = addDays(dueDate, 1);

    state.currentInterest = roundMoney(state.currentInterest + interest);
    state.currentPrincipal = roundMoney(state.currentPrincipal + principal);

    const periodPayments = (ledgerPeriods[i]?.payments || [])
      .map((p) => ({
        date: parseRuDate(p.date),
        amount: toAmount(p.amount),
        label: p.label || '',
      }))
      .filter((p) => p.date && p.amount > 0)
      .sort((a, b) => a.date - b.date);

    const onTime = periodPayments.filter((p) => p.date.getTime() <= dueDate.getTime());
    const late = periodPayments.filter(
      (p) => p.date.getTime() > dueDate.getTime() && p.date.getTime() <= asOfDate.getTime()
    );

    for (const payment of onTime) {
      if (penaltyCursor && overdueBase(state) > 0 && payment.date.getTime() > penaltyCursor.getTime()) {
        pushSegment(segments, {
          debt: overdueBase(state),
          from: penaltyCursor,
          to: payment.date,
          dailyFactor: rate.dailyFactor,
          rateLabel: rate.label,
          closedByPayment: true,
        });
        if (!penaltyFrom) penaltyFrom = formatRuDate(penaltyCursor);
        penaltyCursor = addDays(payment.date, 1);
      }
      applyLegalAllocation(state, payment.amount);
      paymentRows.push({
        date: formatRuDate(payment.date),
        amount: payment.amount,
        label: payment.label,
        appliedBeforePenalty: true,
        debtAfter: overdueBase(state),
      });
      if (overdueBase(state) <= 0) penaltyCursor = null;
    }

    if (penaltyCursor && overdueBase(state) > 0 && dueDate.getTime() > penaltyCursor.getTime()) {
      pushSegment(segments, {
        debt: overdueBase(state),
        from: penaltyCursor,
        to: dueDate,
        dailyFactor: rate.dailyFactor,
        rateLabel: rate.label,
        closedByPayment: false,
      });
      if (!penaltyFrom) penaltyFrom = formatRuDate(penaltyCursor);
    }

    state.overdueInterest = roundMoney(state.overdueInterest + state.currentInterest);
    state.overduePrincipal = roundMoney(state.overduePrincipal + state.currentPrincipal);
    state.currentInterest = 0;
    state.currentPrincipal = 0;

    if (overdueBase(state) > 0) {
      penaltyCursor = dayAfter;
      if (!penaltyFrom) penaltyFrom = formatRuDate(dayAfter);
    } else {
      penaltyCursor = null;
    }

    for (const payment of late) {
      if (penaltyCursor && overdueBase(state) > 0 && payment.date.getTime() > penaltyCursor.getTime()) {
        pushSegment(segments, {
          debt: overdueBase(state),
          from: penaltyCursor,
          to: payment.date,
          dailyFactor: rate.dailyFactor,
          rateLabel: rate.label,
          closedByPayment: true,
        });
      }
      applyLegalAllocation(state, payment.amount);
      paymentRows.push({
        date: formatRuDate(payment.date),
        amount: payment.amount,
        label: payment.label,
        appliedBeforePenalty: false,
        debtAfter: overdueBase(state),
      });
      penaltyCursor = overdueBase(state) > 0 ? addDays(payment.date, 1) : null;
    }

    // хвост периода до следующего due / asOf — начислим в конце цикла на последний период,
    // а между периодами — до due следующей итерации через onTime/dueDate ветки.
    // Здесь фиксируем промежуточный остаток.
    periodResults.push({
      accrual: {
        date: formatRuDate(dueDate),
        amount: total,
        label: `платёж по графику до ${formatRuDate(dueDate)}`,
      },
      penaltyStartDate: formatRuDate(dayAfter),
      remainingDebt: overdueBase(state),
      segments,
      paymentRows,
      excludedAfterAsOf: false,
      _cursor: penaltyCursor,
    });
  }

  // До «сегодня» на последний период
  if (periodResults.length) {
    const last = periodResults[periodResults.length - 1];
    if (last._cursor && overdueBase(state) > 0 && asOfDate.getTime() > last._cursor.getTime()) {
      pushSegment(last.segments, {
        debt: overdueBase(state),
        from: last._cursor,
        to: asOfDate,
        dailyFactor: rate.dailyFactor,
        rateLabel: rate.label,
        closedByPayment: false,
      });
      if (!penaltyFrom) penaltyFrom = formatRuDate(last._cursor);
    }
  }

  for (const period of periodResults) {
    period.penaltyTotal = roundMoney(period.segments.reduce((sum, s) => sum + s.penalty, 0));
    delete period._cursor;
  }

  const penaltyTotal = roundMoney(periodResults.reduce((sum, p) => sum + p.penaltyTotal, 0));

  return {
    asOfDate: formatRuDate(asOfDate),
    rateMode: rate.mode,
    rateLabel: rate.label,
    keyRateToday: rate.keyRateToday,
    dailyFactor: rate.dailyFactor,
    periods: periodResults,
    principalTotal: overdueBase(state),
    penaltyTotal,
    claimAmount: roundMoney(overdueBase(state) + penaltyTotal),
    penaltyFrom,
    penaltyTo: formatRuDate(asOfDate),
    overdueInterest: state.overdueInterest,
    overduePrincipal: state.overduePrincipal,
  };
}
